L["You gave %d buffs unprompted today."] = "Ihr habt heute %d Stärkungszauber unaufgefordert verteilt."
L["All time -- received: %d, returned: %d, given to your group: %d, to strangers: %d"] = "Insgesamt – erhalten: %d, erwidert: %d, an Eure Gruppe verteilt: %d, an Fremde: %d"
L["All time"] = "Insgesamt"
L["received"] = "erhalten"
L["returned"] = "erwidert"
L["to your group"] = "an Eure Gruppe"
